CREATE TABLE IF NOT EXISTS iam.account (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lifecycle_status varchar(16) NOT NULL DEFAULT 'ACTIVE', security_status varchar(24) NOT NULL DEFAULT 'NORMAL', display_name varchar(100) NOT NULL, person_no varchar(100) NOT NULL, person_no_normalized varchar(100) NOT NULL UNIQUE, authz_version bigint NOT NULL DEFAULT 1, credential_version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), row_version bigint NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS iam.login_identity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES iam.account(id) ON DELETE RESTRICT, identity_type varchar(16) NOT NULL, identifier_original text NOT NULL, identifier_normalized text NOT NULL, status varchar(16) NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS ux_login_identity_active ON iam.login_identity(identity_type, identifier_normalized) WHERE status='ACTIVE';
